parameters.text:
=Extract structured information from the following content for use in a LinkedIn post pipeline.

Topic: {{ $('Map Selected Topic').item.json.topic }}
Source type:{{ $('Map Selected Topic').item.json.source_type }}
Content:
{{ $json.text }}

Extract: verified facts (only what's explicitly stated, no inference), the core topic, possible content angles, key technical details, and whether anything here raises privacy or security concerns (e.g. names of real clients, unreleased info, credentials).

parameters.jsCode:
let raw = $input.first().json.data || $input.first().json.html || '';

// Insert line breaks at block-element boundaries BEFORE stripping tags,
// so adjacent elements don't collide into one word (e.g. "DefaultRetrievalDense")
raw = raw.replace(/<\/(p|div|li|h[1-6]|tr|section|article|header|footer|nav)>/gi, '\n');
raw = raw.replace(/<br\s*\/?>/gi, '\n');

let clean = raw
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{2,}/g, '\n\n')
  .trim();

// Strip generic site-noise patterns (not tied to any specific site's markup)
clean = clean.replace(/ESC\s*No results found[\s\S]{0,150}?(Open|Close)\s*/gi, '');
clean = clean.replace(/↑\s*↓\s*Navigate\s*↵?\s*/gi, '');
clean = clean.replace(/Skip to (main )?content\s*/gi, '');
clean = clean.replace(/Accept (all )?cookies[\s\S]{0,100}?(Reject|Decline|OK)?\s*/gi, '');
clean = clean.replace(/Subscribe to (our |my )?newsletter[\s\S]{0,150}?/gi, '');
clean = clean.replace(/Share (this|on)[\s\S]{0,80}?(Twitter|Facebook|LinkedIn)\s*/gi, '');
clean = clean.replace(/^\s*Table of Contents\s*/gim, '');
clean = clean.replace(/Copyright ©?\s*\d{4}[\s\S]{0,100}?rights reserved\.?/gi, '');

// Final whitespace cleanup after all the pattern removals above
clean = clean.replace(/[ \t]+/g, ' ').replace(/\n{2,}/g, '\n\n').trim();

// Cap length to control token usage at Resource Analyzer
const maxChars = 6000;
if (clean.length > maxChars) {
  clean = clean.slice(0, maxChars) + '... [truncated]';
}

return {
  json: {
    ...$input.first().json,
    text: clean
  }
};

